import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;

import '../../../core/services/atomic_file.dart';
import '../domain/task_doc.dart';

/// One JSON file per task in `<root>/.clipboard/tasks/` — the data lives in the
/// workspace folder, never in the app's own storage.
class TaskStore {
  TaskStore(this.root);

  final String root;
  final _lock = AsyncMutex();

  Directory get _dir => Directory(p.join(root, '.clipboard', 'tasks'));

  /// Ids are generated by the app, but the file name must never be able to
  /// escape the tasks folder whatever is passed in.
  File _file(String id) => File(p.join(
      _dir.path, '${id.replaceAll(RegExp(r'[^A-Za-z0-9_-]'), '_')}.json'));

  Future<TaskDoc?> _read(File file) async {
    try {
      return TaskDoc.tryFromJson(
          jsonDecode(await file.readAsString(encoding: utf8)));
    } catch (_) {
      return null;
    }
  }

  Future<TaskDoc?> load(String id) async {
    final file = _file(id);
    return await file.exists() ? _read(file) : null;
  }

  /// All tasks, most recently updated first.
  Future<List<TaskDoc>> loadAll() async {
    if (!await _dir.exists()) return [];
    final tasks = <TaskDoc>[];
    await for (final ent in _dir.list()) {
      if (ent is File && ent.path.endsWith('.json')) {
        final task = await _read(ent);
        if (task != null) tasks.add(task);
      }
    }
    tasks.sort((a, b) => b.updatedAt.compareTo(a.updatedAt));
    return tasks;
  }

  Future<void> save(TaskDoc task) => _lock.run(() async {
        task.updatedAt = DateTime.now();
        await writeStringAtomic(
          _file(task.id),
          const JsonEncoder.withIndent('  ').convert(task.toJson()),
        );
      });

  Future<void> delete(String id) => _lock.run(() async {
        final file = _file(id);
        if (await file.exists()) await file.delete();
      });
}
